SELECT c.idioma, COUNT(*) AS matriculas
FROM matricula m JOIN curso c ON c.id_curso = m.id_curso
GROUP BY c.idioma;

SELECT h.nome, r.numero_quarto, DATEDIFF(r.check_out, r.check_in) AS noites
FROM reserva r JOIN hospede h ON h.id_hospede = r.id_hospede
WHERE r.status = 'finalizada';

SELECT p.nome, COUNT(j.id_jogo) AS qtd_jogos
FROM plataforma p LEFT JOIN jogo j ON j.id_plataforma = p.id_plataforma
GROUP BY p.id_plataforma, p.nome;

SELECT l.nome, SUM(m.preco * m.estoque) AS valor_estoque
FROM laboratorio l JOIN medicamento m ON m.id_lab = l.id_lab
GROUP BY l.id_lab, l.nome;

